// More memory for the Gradle build. expo-updates generates code with KSP, which ran out of
// Metaspace with the template's 512 MB ("java.lang.OutOfMemoryError: Metaspace" in
// :expo-updates:kspReleaseKotlin). android/ is regenerated by prebuild, so it's set here.
const { withGradleProperties } = require("expo/config-plugins");

const JVM_ARGS = "-Xmx2048m -XX:MaxMetaspaceSize=1024m";

module.exports = function withGradleMemory(config) {
  return withGradleProperties(config, (c) => {
    const existing = c.modResults.find((p) => p.type === "property" && p.key === "org.gradle.jvmargs");
    if (existing) existing.value = JVM_ARGS;
    else c.modResults.push({ type: "property", key: "org.gradle.jvmargs", value: JVM_ARGS });
    return c;
  });
};
